(1,'Palette de fards Nude','palette-de-fards-nude-1','BR-0001',3,4,'Nude — Palette de fards signé Rose Éclat, pour un résultat professionnel.','Le Palette de fards Nude de Rose Éclat conjugue efficacité et sensorialité. Sa formule enrichie en actifs sélectionnés sublime votre routine beauté quotidienne. Testé sous contrôle dermatologique, il convient à tous les types de peaux et s''intègre parfaitement à un rituel de soin premium.','Alcohol Denat, Parfum, Aqua, Limonene, Linalool, Citronellol, Geraniol.','Vaporisez à 20 cm de la peau, sur les points de pulsation.',12116,NULL,38,197,'50 ml',4.1,34,0,0,0,0,'active',NULL),
(2,'Anti-cernes Intense','anti-cernes-intense-2','BR-0002',4,2,'Intense — Anti-cernes signé Nour Cosmetics, pour un résultat professionnel.','Le Anti-cernes Intense de Nour Cosmetics conjugue efficacité et sensorialité. Sa formule enrichie en actifs sélectionnés sublime votre routine beauté quotidienne. Testé sous contrôle dermatologique, il convient à tous les types de peaux et s''intègre parfaitement à un rituel de soin premium.','Aqua, Niacinamide, Zinc PCA, Aloe Barbadensis, Allantoin, Sodium Benzoate.','Vaporisez à 20 cm de la peau, sur les points de pulsation.',7935,NULL,71,152,'200 ml',4.9,83,0,0,0,0,'active',NULL),
