-- ============================================================================
--  Bella Rosa — Schéma MySQL 8 (utf8mb4)
--  PDO uniquement · InnoDB · clés étrangères · index · timestamps · soft delete
--  Compatible AwardSpace Free (une seule base de données).
-- ============================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Paramètres du site (clé/valeur) --------------------------------------------
DROP TABLE IF EXISTS settings;
CREATE TABLE settings (
  `key`   VARCHAR(80) NOT NULL PRIMARY KEY,
  `value` TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Administrateurs -------------------------------------------------------------
DROP TABLE IF EXISTS admins;
CREATE TABLE admins (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name       VARCHAR(120) NOT NULL,
  email      VARCHAR(190) NOT NULL UNIQUE,
  password   VARCHAR(255) NOT NULL,
  role       VARCHAR(30)  NOT NULL DEFAULT 'admin',
  created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Marques ---------------------------------------------------------------------
DROP TABLE IF EXISTS brands;
CREATE TABLE brands (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(120) NOT NULL,
  slug        VARCHAR(140) NOT NULL UNIQUE,
  description TEXT NULL,
  logo        VARCHAR(190) NULL,
  deleted_at  TIMESTAMP NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Catégories (hiérarchie) -----------------------------------------------------
DROP TABLE IF EXISTS categories;
CREATE TABLE categories (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  parent_id  INT UNSIGNED NULL,
  name       VARCHAR(120) NOT NULL,
  slug       VARCHAR(140) NOT NULL UNIQUE,
  icon       VARCHAR(40)  NULL,
  description TEXT NULL,
  image      VARCHAR(190) NULL,
  seo_title  VARCHAR(190) NULL,
  seo_desc   VARCHAR(255) NULL,
  position   INT NOT NULL DEFAULT 0,
  deleted_at TIMESTAMP NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_cat_parent (parent_id),
  CONSTRAINT fk_cat_parent FOREIGN KEY (parent_id) REFERENCES categories(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Produits --------------------------------------------------------------------
DROP TABLE IF EXISTS products;
CREATE TABLE products (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name          VARCHAR(190) NOT NULL,
  slug          VARCHAR(210) NOT NULL UNIQUE,
  sku           VARCHAR(40)  NOT NULL UNIQUE,
  brand_id      INT UNSIGNED NULL,
  category_id   INT UNSIGNED NULL,
  short_desc    VARCHAR(400) NULL,
  long_desc     TEXT NULL,
  ingredients   TEXT NULL,
  usage_tips    TEXT NULL,
  price         DECIMAL(10,2) NOT NULL DEFAULT 0,
  old_price     DECIMAL(10,2) NULL,
  stock         INT NOT NULL DEFAULT 0,
  weight        INT NULL,
  volume        VARCHAR(30) NULL,
  rating        DECIMAL(2,1) NOT NULL DEFAULT 0,
  reviews_count INT NOT NULL DEFAULT 0,
  is_featured   TINYINT(1) NOT NULL DEFAULT 0,
  is_new        TINYINT(1) NOT NULL DEFAULT 0,
  is_bestseller TINYINT(1) NOT NULL DEFAULT 0,
  on_sale       TINYINT(1) NOT NULL DEFAULT 0,
  status        VARCHAR(20) NOT NULL DEFAULT 'active',
  video_url     VARCHAR(255) NULL,
  deleted_at    TIMESTAMP NULL,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_prod_cat (category_id),
  INDEX idx_prod_brand (brand_id),
  INDEX idx_prod_flags (is_featured, is_new, is_bestseller, on_sale),
  INDEX idx_prod_price (price),
  CONSTRAINT fk_prod_brand FOREIGN KEY (brand_id) REFERENCES brands(id) ON DELETE SET NULL,
  CONSTRAINT fk_prod_cat   FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Galerie produit -------------------------------------------------------------
DROP TABLE IF EXISTS product_images;
CREATE TABLE product_images (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  product_id INT UNSIGNED NOT NULL,
  file       VARCHAR(190) NOT NULL,
  position   INT NOT NULL DEFAULT 0,
  INDEX idx_img_product (product_id),
  CONSTRAINT fk_img_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Clients ---------------------------------------------------------------------
DROP TABLE IF EXISTS customers;
CREATE TABLE customers (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  first_name     VARCHAR(80) NOT NULL,
  last_name      VARCHAR(80) NOT NULL,
  email          VARCHAR(190) NOT NULL UNIQUE,
  phone          VARCHAR(30) NULL,
  password       VARCHAR(255) NOT NULL,
  wilaya         VARCHAR(60) NULL,
  loyalty_points INT NOT NULL DEFAULT 0,
  deleted_at     TIMESTAMP NULL,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Adresses --------------------------------------------------------------------
DROP TABLE IF EXISTS addresses;
CREATE TABLE addresses (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  customer_id INT UNSIGNED NOT NULL,
  label       VARCHAR(60) NULL,
  line1       VARCHAR(190) NOT NULL,
  city        VARCHAR(80) NULL,
  wilaya      VARCHAR(60) NULL,
  phone       VARCHAR(30) NULL,
  is_default  TINYINT(1) NOT NULL DEFAULT 0,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_addr_customer (customer_id),
  CONSTRAINT fk_addr_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Avis produits ---------------------------------------------------------------
DROP TABLE IF EXISTS reviews;
CREATE TABLE reviews (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  product_id  INT UNSIGNED NOT NULL,
  customer_id INT UNSIGNED NULL,
  author_name VARCHAR(120) NOT NULL,
  rating      TINYINT NOT NULL DEFAULT 5,
  title       VARCHAR(160) NULL,
  body        TEXT NULL,
  status      VARCHAR(20) NOT NULL DEFAULT 'pending',
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_rev_product (product_id),
  INDEX idx_rev_status (status),
  CONSTRAINT fk_rev_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Commandes -------------------------------------------------------------------
DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  reference      VARCHAR(40) NOT NULL UNIQUE,
  customer_id    INT UNSIGNED NULL,
  customer_name  VARCHAR(160) NOT NULL,
  email          VARCHAR(190) NULL,
  phone          VARCHAR(30) NULL,
  address        VARCHAR(255) NULL,
  wilaya         VARCHAR(60) NULL,
  subtotal       DECIMAL(10,2) NOT NULL DEFAULT 0,
  shipping       DECIMAL(10,2) NOT NULL DEFAULT 0,
  discount       DECIMAL(10,2) NOT NULL DEFAULT 0,
  total          DECIMAL(10,2) NOT NULL DEFAULT 0,
  payment_method VARCHAR(30) NOT NULL DEFAULT 'cod',
  status         VARCHAR(20) NOT NULL DEFAULT 'pending',
  note           TEXT NULL,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_order_customer (customer_id),
  INDEX idx_order_status (status),
  CONSTRAINT fk_order_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Lignes de commande ----------------------------------------------------------
DROP TABLE IF EXISTS order_items;
CREATE TABLE order_items (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  order_id   INT UNSIGNED NOT NULL,
  product_id INT UNSIGNED NULL,
  name       VARCHAR(190) NOT NULL,
  price      DECIMAL(10,2) NOT NULL DEFAULT 0,
  qty        INT NOT NULL DEFAULT 1,
  INDEX idx_oi_order (order_id),
  CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Coupons / promotions --------------------------------------------------------
DROP TABLE IF EXISTS coupons;
CREATE TABLE coupons (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  code        VARCHAR(40) NOT NULL UNIQUE,
  type        VARCHAR(10) NOT NULL DEFAULT 'percent',
  value       DECIMAL(10,2) NOT NULL DEFAULT 0,
  min_amount  DECIMAL(10,2) NOT NULL DEFAULT 0,
  description VARCHAR(190) NULL,
  expires_at  DATE NULL,
  usage_limit INT NOT NULL DEFAULT 0,
  used        INT NOT NULL DEFAULT 0,
  active      TINYINT(1) NOT NULL DEFAULT 1,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Blog ------------------------------------------------------------------------
DROP TABLE IF EXISTS blog_posts;
CREATE TABLE blog_posts (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  title        VARCHAR(190) NOT NULL,
  slug         VARCHAR(210) NOT NULL UNIQUE,
  category     VARCHAR(60) NULL,
  excerpt      VARCHAR(400) NULL,
  body         MEDIUMTEXT NULL,
  image        VARCHAR(190) NULL,
  author       VARCHAR(120) NULL,
  tags         VARCHAR(255) NULL,
  seo_title    VARCHAR(190) NULL,
  seo_desc     VARCHAR(255) NULL,
  status       VARCHAR(20) NOT NULL DEFAULT 'published',
  views        INT NOT NULL DEFAULT 0,
  published_at TIMESTAMP NULL,
  deleted_at   TIMESTAMP NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_blog_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Témoignages -----------------------------------------------------------------
DROP TABLE IF EXISTS testimonials;
CREATE TABLE testimonials (
  id       INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  name     VARCHAR(120) NOT NULL,
  role     VARCHAR(120) NULL,
  avatar   VARCHAR(190) NULL,
  rating   TINYINT NOT NULL DEFAULT 5,
  body     TEXT NULL,
  position INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Liste de souhaits -----------------------------------------------------------
DROP TABLE IF EXISTS wishlists;
CREATE TABLE wishlists (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  customer_id INT UNSIGNED NOT NULL,
  product_id  INT UNSIGNED NOT NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uniq_wish (customer_id, product_id),
  CONSTRAINT fk_wish_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE,
  CONSTRAINT fk_wish_product  FOREIGN KEY (product_id)  REFERENCES products(id)  ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Newsletter ------------------------------------------------------------------
DROP TABLE IF EXISTS newsletter;
CREATE TABLE newsletter (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  email      VARCHAR(190) NOT NULL UNIQUE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

